package pe.edu.solucionesweb.tramite.model;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="derivaciones") public class Derivacion { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) private Tramite tramite; @ManyToOne(optional=false) private Area areaDestino; private String responsable; private String observacion; private LocalDateTime fecha; public Long getId(){return id;} public Tramite getTramite(){return tramite;} public void setTramite(Tramite v){tramite=v;} public Area getAreaDestino(){return areaDestino;} public void setAreaDestino(Area v){areaDestino=v;} public String getResponsable(){return responsable;} public void setResponsable(String v){responsable=v;} public String getObservacion(){return observacion;} public void setObservacion(String v){observacion=v;} public LocalDateTime getFecha(){return fecha;} public void setFecha(LocalDateTime v){fecha=v;} }
